{"implementation":"def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])
    # Build maps
    id2node = {}
    children = {}
    for n in nodes:
        nid = n['id']
        id2node[nid] = n
        children[nid] = []
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children[pid].append(n['id'])
    # Validate required symbols exist
    all_symbols = {n['symbol'] for n in nodes}
    if not required_symbols.issubset(all_symbols):
        raise ValueError('Required symbols not present in tree')
    # Initialise state
    symbol_counts = {}
    for n in nodes:
        sym = n['symbol']
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
    removed_ids = set()
    removal_order = []
    # Sort nodes: deeper first, then by id
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for node in sorted_nodes:
        nid = node['id']
        # Cannot remove if not removable
        if not node['removable']:
            continue
        # Cannot remove root (already not removable but check anyway)
        if nid == 'root':
            continue
        # Cannot remove a required symbol
        if node['symbol'] in required_symbols:
            continue
        # Cannot remove if has retained children
        has_retained_child = any(cid not in removed_ids for cid in children[nid])
        if has_retained_child:
            continue
        # Check that all required symbols remain after removal
        ok = True
        for rsym in required_symbols:
            cnt = symbol_counts[rsym] - (1 if node['symbol'] == rsym else 0)
            if cnt < 1:
                ok = False
                break
        if not ok:
            continue
        # Perform removal
        removed_ids.add(nid)
        removal_order.append(nid)
        symbol_counts[node['symbol']] -= 1
    # Build retained set
    all_ids = {n['id'] for n in nodes}
    retained_ids = sorted(all_ids - removed_ids)
    return {'retained': retained_ids, 'removal_order': removal_order}"}
